## Takes prompt from command line (in quotation marks)# Outputs to console#import argparsefrom openaicalls_cmd_v2 import make_llmfrom langchain.chains import RetrievalQAfrom langchain_community.vectorstores import Chromadef main():    # Parse the command-line argument for the prompt    parser = argparse.ArgumentParser(        description="A simple RAG chatbot client that takes a prompt and returns an LLM response."    )    parser.add_argument("prompt", type=str, help="The prompt to ask the chatbot")    args = parser.parse_args()        # Initialize the LLM and embedding function    model, emb = make_llm()        # Load the vectorstore (assumes your Chroma database is set up at ../database/chroma_db)    vectorstore = Chroma(        persist_directory="./chroma_db",        embedding_function=emb    )        # Create a RetrievalQA chain that uses the vectorstore to fetch relevant documents.    # Here, the chain type "stuff" is used for simplicity.    qa_chain = RetrievalQA.from_chain_type(        llm=model,        chain_type="stuff",        retriever=vectorstore.as_retriever(search_kwargs={"k": 5})    )        # Run the chain with the user-provided prompt    response = qa_chain.run(args.prompt)        # Output the response to the console    print("Response:")    print(response)if __name__ == "__main__":    main()